-- M62601: HSK 6 · HSK 3.0 загвар шалгалт №1 (全真模拟) — 全真模拟 (BLCUP 2026), HSK 3.0 шинэ бүтэц. 82 асуулт, 115 мин. Аудио/зураг: public/mock-tests/m62601/
-- Дахин ажиллуулахад аюулгүй (upsert).
begin;
insert into public.mock_tests (id, hsk_level, title, total_questions, time_limit_min, has_writing, sections, is_active)
values ('M62601', 6, 'HSK 6 · HSK 3.0 загвар шалгалт №1 (全真模拟)', 82, 115, true, '[{"skill": "listening", "audio_url": "/mock-tests/m62601/listening.mp3", "time_min": 30, "parts": [{"part": 1, "range": [1, 8], "q_type": "choice", "desc": "Богино мэдээ → агуулгатай таарах сонголт"}, {"part": 2, "range": [9, 28], "q_type": "choice", "desc": "Богино өгүүлэл → асуулт (сонголт)"}, {"part": 3, "range": [29, 40], "q_type": "choice", "desc": "Ярилцлага → асуулт (сонголт)"}]}, {"skill": "reading", "audio_url": null, "time_min": 40, "parts": [{"part": 1, "range": [41, 50], "q_type": "choice", "desc": "Үг сонгож нөхөх"}, {"part": 2, "range": [51, 60], "q_type": "fill_word", "desc": "Өгүүлбэр сонгож нөхөх"}, {"part": 3, "range": [61, 80], "q_type": "choice", "desc": "Урт эх унших → асуулт (сонголт)"}]}, {"skill": "writing", "audio_url": null, "time_min": 45, "parts": [{"part": 1, "range": [81, 81], "q_type": "essay", "desc": "Хэрэглээний бичвэр (өргөдлийн захидал)"}, {"part": 2, "range": [82, 82], "q_type": "essay", "desc": "Санал бодлоо илэрхийлэх эссэ"}]}]'::jsonb, true)
