insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M62601','listening',1,1,'choice','','[{"key": "A", "text": "老人更希望能与子女住在一起"}, {"key": "B", "text": "抱团养老模式能消除生活矛盾"}, {"key": "C", "text": "子女不需要再承担养老责任了"}, {"key": "D", "text": "抱团养老模式能提供情感支持"}]'::jsonb,'D','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «这种模式……缓解了老年人的孤独感» гэж хэлсэн. Өөрөөр хэлбэл хамт амьдрах нь настанд сэтгэлийн дэмжлэг өгдөг тул D зөв.',43.28,85.78,'随着社会老龄化程度的加深，“抱团养老”模式在城市中逐渐兴起。几位爱好相同的老年朋友住在一起，互相照顾，共同分担家务。这种模式既减轻了子女的压力，也在一定程度上缓解了老年人的孤独感。虽然共同生活难免产生相互适应等问题，但其展现的互助精神，为社会养老提供了新参考。','{"why": "Эх «这种模式……缓解了老年人的孤独感» гэж хэлсэн. Өөрөөр хэлбэл хамт амьдрах нь настанд сэтгэлийн дэмжлэг өгдөг тул D зөв.", "key": "缓解了老年人的孤独感", "keyMn": "Настны ганцаардлыг багасгадаг", "wrong": {"A": "Эхэд «хүүхдийн дарамтыг багасгана» гэсэн ч настан хүүхэдтэйгээ амьдрахыг илүү хүснэ гэж хэлээгүй.", "B": "«难免产生相互适应等问题» гэсэн тул зөрчил арилаагүй.", "C": "Дарамт багасах нь хариуцлагаас бүрмөсөн чөлөөлөгдөх гэсэн үг биш, хэтрүүлсэн дүгнэлт."}, "words": [{"zh": "抱团养老", "pinyin": "bàotuán yǎnglǎo", "mn": "хамтдаа өтлөх асрамж"}, {"zh": "孤独感", "pinyin": "gūdúgǎn", "mn": "ганцаардлын мэдрэмж"}, {"zh": "缓解", "pinyin": "huǎnjiě", "mn": "намжаах, багасгах"}, {"zh": "互助", "pinyin": "hùzhù", "mn": "харилцан тусалцах"}], "tip": "Сонголт дахь «不需要……了», «消除» зэрэг үг хэтрүүлсэн байвал сэжиглэ.", "transcript": [{"zh": "随着社会老龄化程度的加深，“抱团养老”模式在城市中逐渐兴起。", "mn": "Нийгэм хөгширөх тусам хотуудад хамтдаа өтлөх хэлбэр бий болж байна."}, {"zh": "几位爱好相同的老年朋友住在一起，互相照顾，共同分担家务。", "mn": "Нэгэн адил сонирхолтой хэдэн настан нэг дор амьдарч, бие биенээ асарч, ахуйн ажлаа хуваан хийдэг."}, {"zh": "这种模式既减轻了子女的压力，也在一定程度上缓解了老年人的孤独感。", "mn": "Энэ хэлбэр хүүхдүүдийн дарамтыг багасгаж, настны ганцаардлыг тодорхой хэмжээгээр намжаадаг."}, {"zh": "虽然共同生活难免产生相互适应等问题，但其展现的互助精神，为社会养老提供了新参考。", "mn": "Хамт амьдрахад бие биедээ дасан зохицох зэрэг асуудал гарах нь гарцаагүй ч, харилцан тусалцах сэтгэл нь өндөр настны асрамжид шинэ жишиг болж байна."}]}'::jsonb),
('M62601','listening',1,2,'choice','','[{"key": "A", "text": "预制菜的种类非常丰富"}, {"key": "B", "text": "传统厨师已被工厂取代"}, {"key": "C", "text": "预制菜在口感上存在不足"}, {"key": "D", "text": "工业生产能让食物更美味"}]'::jsonb,'C','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «预制菜虽然省时，味道却不如现做出来的好» гэсэн. Иймд амт, мэдрэмжийн хувьд дутагдалтай гэсэн C зөв.',86.08,127.72,'近年来，预制菜因方便、快捷在城市中受到欢迎。然而，关于它是否健康、是否有特色的讨论从未停止。很多人认为，美食离不开现场烹饪，预制菜虽然省时，味道却不如现做出来的好。如何在工业化生产与传统厨艺间寻找平衡点，是餐饮业面临的新挑战。','{"why": "Эх «预制菜虽然省时，味道却不如现做出来的好» гэсэн. Иймд амт, мэдрэмжийн хувьд дутагдалтай гэсэн C зөв.", "key": "味道却不如现做出来的好", "keyMn": "Амт нь шинээр хийснээс дор", "wrong": {"A": "Зөвхөн «方便、快捷» гэсэн; төрөл олон гэдгийг дурдаагүй.", "B": "Эцэст нь «传统厨艺»-тэй тэнцвэр олох гэсэн, тиймээс тогооч орлогдоогүй.", "D": "Эхийн санаа эсрэг: «美食离不开现场烹饪»."}, "words": [{"zh": "预制菜", "pinyin": "yùzhìcài", "mn": "урьдчилан бэлтгэсэн хоол"}, {"zh": "口感", "pinyin": "kǒugǎn", "mn": "амт, идэхэд мэдрэгдэх байдал"}, {"zh": "烹饪", "pinyin": "pēngrèn", "mn": "хоол хийх"}, {"zh": "平衡点", "pinyin": "pínghéngdiǎn", "mn": "тэнцвэрийн цэг"}], "tip": "«虽然……却……»: ард нь байгаа хэсэг нь гол санаа.", "transcript": [{"zh": "近年来，预制菜因方便、快捷在城市中受到欢迎。", "mn": "Сүүлийн жилүүдэд урьдчилан бэлтгэсэн хоол амар, хурдан тул хотуудад дуртай болж байна."}, {"zh": "然而，关于它是否健康、是否有特色的讨论从未停止。", "mn": "Гэвч энэ нь эрүүл үү, онцлогтой юу гэсэн маргаан хэзээ ч зогссонгүй."}, {"zh": "很多人认为，美食离不开现场烹饪，预制菜虽然省时，味道却不如现做出来的好。", "mn": "Олон хүн «сайхан хоол газар дээрээ хийж бэлтгэхээс салшгүй, урьдчилан бэлтгэсэн хоол цаг хэмнэдэг ч амт нь шинээр хийснээс дор» гэж үздэг."}, {"zh": "如何在工业化生产与传统厨艺间寻找平衡点，是餐饮业面临的新挑战。", "mn": "Үйлдвэрийн үйлдвэрлэл ба уламжлалт хоол хийх урлагийн хооронд тэнцвэр олох нь хоолны салбарын шинэ сорилт юм."}]}'::jsonb),
('M62601','listening',1,3,'choice','','[{"key": "A", "text": "深色模式适合强光环境"}, {"key": "B", "text": "长期在暗处看手机伤眼"}, {"key": "C", "text": "护眼关键在于调节亮度"}, {"key": "D", "text": "专家建议停用深色模式"}]'::jsonb,'B','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «长期在完全黑暗中使用该模式，反而会对视力造成伤害» гэсэн. Тиймээс удаан харанхуйд утас харах нь нүдэнд муу гэсэн B зөв.',128.02,167.92,'为了保护视力，许多人喜欢将手机设置为“深色模式”。这种模式在光线暗的环境下，确实能减轻眼睛的疲劳感。但专家提醒，长期在完全黑暗中使用该模式，反而会对视力造成伤害。保护眼睛的关键，不在于选择哪种显示模式，而在于控制手机的使用时间。','{"why": "Эх «长期在完全黑暗中使用该模式，反而会对视力造成伤害» гэсэн. Тиймээс удаан харанхуйд утас харах нь нүдэнд муу гэсэн B зөв.", "key": "长期在完全黑暗中使用该模式，反而会对视力造成伤害", "keyMn": "Удаан хугацаагаар бүрэн харанхуйд ашиглавал нүдэнд хор болно", "wrong": {"A": "Харанхуй горим «光线暗的环境»-д тохиромжтой, хурц гэрэлд биш.", "C": "Гол нь «控制使用时间», гэрлийн тохиргоо биш.", "D": "Мэргэжилтэн зөвхөн сануулсан, ашиглахыг зогсоо гэж хэлээгүй."}, "words": [{"zh": "深色模式", "pinyin": "shēnsè móshì", "mn": "харанхуй горим"}, {"zh": "视力", "pinyin": "shìlì", "mn": "нүдний хараа"}, {"zh": "疲劳", "pinyin": "píláo", "mn": "ядаргаа"}, {"zh": "控制", "pinyin": "kòngzhì", "mn": "хянах"}], "transcript": [{"zh": "为了保护视力，许多人喜欢将手机设置为“深色模式”。", "mn": "Нүдээ хамгаалахын тулд олон хүн утсаа «харанхуй горим»-д тохируулах дуртай."}, {"zh": "这种模式在光线暗的环境下，确实能减轻眼睛的疲劳感。", "mn": "Энэ горим гэрэл бүдэг орчинд нүдний ядаргааг үнэхээр багасгадаг."}, {"zh": "但专家提醒，长期在完全黑暗中使用该模式，反而会对视力造成伤害。", "mn": "Гэвч мэргэжилтнүүд бүрэн харанхуйд удаан хугацаагаар ашиглавал нүдний хараанд эсрэгээрээ хор хөнөөл учруулна гэж сануулдаг."}, {"zh": "保护眼睛的关键，不在于选择哪种显示模式，而在于控制手机的使用时间。", "mn": "Нүдээ хамгаалах гол нь ямар горим сонгохдоо биш, утсаа хэр удаан ашиглахаа хянахад оршино."}]}'::jsonb),
('M62601','listening',1,4,'choice','','[{"key": "A", "text": "共享单车增加了交通压力"}, {"key": "B", "text": "技术手段有助于规范停车"}, {"key": "C", "text": "用户反对定位技术的应用"}, {"key": "D", "text": "乱停乱放的问题无法解决"}]'::jsonb,'B','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «运用定位技术进行管理……规范了停车秩序» гэсэн тул технологи зогсоолын дэг журмыг сайжруулсан гэсэн B зөв.',168.22,210.5,'共享单车为城市出行提供了便利，但也带来了乱停乱放的问题。为了解决这个问题，许多城市设置了专门的停车区域，并运用定位技术进行管理。用户必须将单车停在规定地点，否则无法结束行程，费用就会随之增加。这种方式规范了停车秩序，提高了管理水平，有效改善了城市环境。','{"why": "Эх «运用定位技术进行管理……规范了停车秩序» гэсэн тул технологи зогсоолын дэг журмыг сайжруулсан гэсэн B зөв.", "key": "运用定位技术进行管理，规范了停车秩序", "keyMn": "Байршил тогтоох технологиор удирдаж, зогсоолыг цэгцэлсэн", "wrong": {"A": "Дугуй «提供了便利» гэсэн, тээврийн ачаалал нэмсэн гэж хэлээгүй.", "C": "Хэрэглэгч эсэргүүцсэн гэсэн зүйл эхэд алга.", "D": "Эцэст нь «有效改善了城市环境» тул асуудал шийдэгдсэн."}, "words": [{"zh": "共享单车", "pinyin": "gòngxiǎng dānchē", "mn": "хамтын дугуй"}, {"zh": "乱停乱放", "pinyin": "luàn tíng luàn fàng", "mn": "дур мэдэн зогсоох"}, {"zh": "定位", "pinyin": "dìngwèi", "mn": "байршил тогтоох"}, {"zh": "规范", "pinyin": "guīfàn", "mn": "цэгцлэх, жигдрүүлэх"}], "transcript": [{"zh": "共享单车为城市出行提供了便利，但也带来了乱停乱放的问题。", "mn": "Хамтын дугуй хотод явахад тав тух өгсөн ч, дур мэдэн зогсоох асуудал дагуулсан."}, {"zh": "为了解决这个问题，许多城市设置了专门的停车区域，并运用定位技术进行管理。", "mn": "Үүнийг шийдэхийн тулд олон хотод тусгай зогсоолын хэсэг гаргаж, байршил тодорхойлох технологиор удирддаг болсон."}, {"zh": "用户必须将单车停在规定地点，否则无法结束行程，费用就会随之增加。", "mn": "Хэрэглэгч дугуйгаа заасан газарт зогсоох ёстой, эс бөгөөс аяллаа дуусгаж болохгүй бөгөөд төлбөр нь нэмэгддэг."}, {"zh": "这种方式规范了停车秩序，提高了管理水平，有效改善了城市环境。", "mn": "Ийм арга зогсоолын дэг журмыг сайжруулж, удирдлагын түвшинг дээшлүүлж, хотын орчныг үр дүнтэй сайжруулсан."}]}'::jsonb),
('M62601','listening',1,5,'choice','','[{"key": "A", "text": "线上就诊将取代传统就诊"}, {"key": "B", "text": "医院的运行成本明显下降"}, {"key": "C", "text": "线上就诊提高了医疗效率"}, {"key": "D", "text": "所有疾病都适合在线咨询"}]'::jsonb,'C','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «提高了医疗效率，缓解了医院压力» гэсэн. Тиймээс онлайн үзлэг эмчилгээний үр ашгийг нэмсэн гэсэн C зөв.',210.8,254.35,'随着互联网技术的普及，“线上看病”变得越来越流行。患者通过手机就能咨询医生，省去了排队时间。这种模式尤其适合一些患常见疾病或长期服药的患者。虽然线上交流无法完全代替面对面就诊，但它提高了医疗效率，缓解了医院压力，为大众看病提供了更多便利。','{"why": "Эх «提高了医疗效率，缓解了医院压力» гэсэн. Тиймээс онлайн үзлэг эмчилгээний үр ашгийг нэмсэн гэсэн C зөв.", "key": "它提高了医疗效率", "keyMn": "Энэ нь эмчилгээний үр ашгийг нэмсэн", "wrong": {"A": "«无法完全代替面对面就诊» гэсэн тул орлохгүй.", "B": "«缓解了医院压力» гэсэн, зардал буурсан гэж хэлээгүй.", "D": "Зөвхөн энгийн болон удаан эмчлүүлэгч өвчтөнд тохиромжтой гэсэн."}, "words": [{"zh": "线上看病", "pinyin": "xiànshàng kànbìng", "mn": "онлайнаар эмчид үзүүлэх"}, {"zh": "咨询", "pinyin": "zīxún", "mn": "зөвлөгөө авах"}, {"zh": "面对面", "pinyin": "miànduìmiàn", "mn": "биечлэн"}, {"zh": "效率", "pinyin": "xiàolǜ", "mn": "үр ашиг"}], "tip": "«所有», «完全» зэрэг үг орсон сонголт ихэвчлэн буруу.", "transcript": [{"zh": "随着互联网技术的普及，“线上看病”变得越来越流行。", "mn": "Интернет технологи дэлгэрэхийн хэрээр «онлайн үзлэг» улам түгээмэл болж байна."}, {"zh": "患者通过手机就能咨询医生，省去了排队时间。", "mn": "Өвчтөн утсаараа эмчээс зөвлөгөө аваад, дараалал хүлээх цагаа хэмнэдэг."}, {"zh": "这种模式尤其适合一些患常见疾病或长期服药的患者。", "mn": "Энэ арга ялангуяа энгийн өвчтэй эсвэл удаан хугацаагаар эм уудаг өвчтөнд тохиромжтой."}, {"zh": "虽然线上交流无法完全代替面对面就诊，但它提高了医疗效率，缓解了医院压力，为大众看病提供了更多便利。", "mn": "Онлайн харилцаа нь биечлэн үзүүлэхийг бүрэн орлож чадахгүй ч эмчилгээний үр ашгийг нэмэгдүүлж, эмнэлгийн ачааллыг багасгаж, олон түмэнд эмчлүүлэхэд илүү хялбар болгосон."}]}'::jsonb),
('M62601','listening',1,6,'choice','','[{"key": "A", "text": "城市人拒绝去农村旅游"}, {"key": "B", "text": "乡村旅游能节省旅游费用"}, {"key": "C", "text": "乡村旅游能促进经济增长"}, {"key": "D", "text": "乡村旅游导致农村人口减少"}]'::jsonb,'C','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «带动了消费，促进了当地的经济发展» гэсэн. Тиймээс хөдөөгийн аялал эдийн засгийг дэмждэг гэсэн C зөв.',254.65,294.02,'如今，乡村旅游成为不少城市人度假的首选。游客走进农村，在放松身心的同时，也带动了消费，促进了当地的经济发展。为展现乡村特色，各地持续改善生态环境与公共设施。这不仅体现了生活水平的提升，也为农村发展提供了相应支持，促进了城乡文化的融合与认同。','{"why": "Эх «带动了消费，促进了当地的经济发展» гэсэн. Тиймээс хөдөөгийн аялал эдийн засгийг дэмждэг гэсэн C зөв.", "key": "促进了当地的经济发展", "keyMn": "Нутгийн эдийн засгийн хөгжилд түлхэц өгсөн", "wrong": {"A": "Эхэнд «度假的首选» гэсэн, татгалзаж байгаа юм алга.", "B": "Хэрэглээг нэмсэн гэсэн, аяллын зардал хэмнэнэ гэсэн зүйл алга.", "D": "Хөдөөгийн хүн амын тухай огт яриагүй."}, "words": [{"zh": "乡村旅游", "pinyin": "xiāngcūn lǚyóu", "mn": "хөдөөгийн аялал жуулчлал"}, {"zh": "带动", "pinyin": "dàidòng", "mn": "түлхэц өгөх, дагуулах"}, {"zh": "消费", "pinyin": "xiāofèi", "mn": "хэрэглээ"}, {"zh": "融合", "pinyin": "rónghé", "mn": "нэгдэх, уялдах"}], "transcript": [{"zh": "如今，乡村旅游成为不少城市人度假的首选。", "mn": "Одоо хөдөөгийн аялал жуулчлал олон хотынхны амралтын тэргүүн сонголт болж байна."}, {"zh": "游客走进农村，在放松身心的同时，也带动了消费，促进了当地的经济发展。", "mn": "Жуулчид хөдөө очиж, оюун бие тайвшрахын зэрэгцээ хэрэглээг өсгөж, тухайн нутгийн эдийн засгийн хөгжилд түлхэц өгдөг."}, {"zh": "为展现乡村特色，各地持续改善生态环境与公共设施。", "mn": "Хөдөөгийн онцлогийг харуулахын тулд газар бүр байгаль орчин, нийтийн байгууламжаа тасралтгүй сайжруулж байна."}, {"zh": "这不仅体现了生活水平的提升，也为农村发展提供了相应支持，促进了城乡文化的融合与认同。", "mn": "Энэ нь амьдралын түвшин дээшилснийг илтгэхээс гадна хөдөөгийн хөгжилд дэмжлэг болж, хот хөдөөгийн соёлын уялдаа, хүлээн зөвшөөрөлтийг гүнзгийрүүлсэн."}]}'::jsonb),
('M62601','listening',1,7,'choice','','[{"key": "A", "text": "现在的年轻人工作不努力"}, {"key": "B", "text": "职场新人完全不看重薪水"}, {"key": "C", "text": "薪水是择业时唯一的标准"}, {"key": "D", "text": "完善的福利能够吸引人才"}]'::jsonb,'D','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «完善的福利……会比单纯的高薪更有吸引力» гэсэн. Тиймээс сайн хангамж чадвартай хүмүүсийг татдаг гэсэн D зөв.',294.32,337.24,'现在的职场新人就业观念发生了转变，他们不仅关注薪水，更看重工作的“幸福感”。调查显示，如果公司能提供免费体检、弹性工作制以及完善的福利，会比单纯的高薪更有吸引力。年轻人希望在努力工作的同时，也能拥有属于自己的私人时间，实现生活与工作的平衡。','{"why": "Эх «完善的福利……会比单纯的高薪更有吸引力» гэсэн. Тиймээс сайн хангамж чадвартай хүмүүсийг татдаг гэсэн D зөв.", "key": "完善的福利……更有吸引力", "keyMn": "Бүрэн хангамж илүү сонирхол татна", "wrong": {"A": "Залуус «努力工作» хийхийг хүсдэг, залхуу гэсэн зүйл алга.", "B": "«不仅关注薪水» гэсэн нь цалинд огт хайхрамжгүй гэсэн үг биш.", "C": "«不仅……更……» бүтэц тул цалин цорын ганц шалгуур биш."}, "words": [{"zh": "福利", "pinyin": "fúlì", "mn": "хангамж, хөнгөлөлт"}, {"zh": "薪水", "pinyin": "xīnshui", "mn": "цалин"}, {"zh": "弹性工作制", "pinyin": "tánxìng gōngzuòzhì", "mn": "уян хатан ажлын цагийн дэглэм"}, {"zh": "平衡", "pinyin": "pínghéng", "mn": "тэнцвэр"}], "tip": "«不仅……更……»: нэмэлт үг дээрх нь илүү чухал.", "transcript": [{"zh": "现在的职场新人就业观念发生了转变，他们不仅关注薪水，更看重工作的“幸福感”。", "mn": "Одоогийн ажилд шинээр орсон залуус хөдөлмөр эрхлэлтийн үзэл бодлоо өөрчилсөн: цалинд анхаарахаас гадна ажлын «аз жаргал»-ыг илүү үнэлдэг болсон."}, {"zh": "调查显示，如果公司能提供免费体检、弹性工作制以及完善的福利，会比单纯的高薪更有吸引力。", "mn": "Судалгаагаар компани үнэгүй үзлэг шинжилгээ, уян хатан ажлын цаг, бүрэн хангамж өгвөл зөвхөн өндөр цалингаас илүү татагдана гэж гарчээ."}, {"zh": "年轻人希望在努力工作的同时，也能拥有属于自己的私人时间，实现生活与工作的平衡。", "mn": "Залуус шаргуу ажиллахын зэрэгцээ хувийн цагтай байж, ажил амьдралынхаа тэнцвэрт хүрэхийг хүсдэг."}]}'::jsonb),
('M62601','listening',1,8,'choice','','[{"key": "A", "text": "武汉经济发展比较缓慢"}, {"key": "B", "text": "游客对来武汉不感兴趣"}, {"key": "C", "text": "交通位置影响经济发展"}, {"key": "D", "text": "武汉历史街区已全拆除"}]'::jsonb,'C','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «作为连接各地的交通中心，武汉在经济发展中展现出巨大的潜力» гэсэн. Тээврийн байршил эдийн засагт нөлөөтэй гэсэн C зөв.',337.54,391.85,'武汉作为中国历史文化名城，拥有丰富的文化遗产。如今，这座历史悠久的商业中心已发展成为充满活力的现代都市。通过科技创新与文旅融合，古老的历史街区获得了新的生命力。作为连接各地的交通中心，武汉在经济发展中展现出巨大的潜力，吸引着世界各地的游客。','{"why": "Эх «作为连接各地的交通中心，武汉在经济发展中展现出巨大的潜力» гэсэн. Тээврийн байршил эдийн засагт нөлөөтэй гэсэн C зөв.", "key": "作为连接各地的交通中心，武汉在经济发展中展现出巨大的潜力", "keyMn": "Тээврийн төв тул эдийн засгийн хөгжилд асар их нөөцтэй", "wrong": {"A": "Эрч хүчтэй хот, асар их нөөцтэй гэсэн тул удаан гэж болохгүй.", "B": "«吸引着世界各地的游客».", "D": "Түүхэт гудамж «获得了新的生命力», нураагаагүй."}, "words": [{"zh": "历史文化名城", "pinyin": "lìshǐ wénhuà míngchéng", "mn": "түүх соёлын алдартай хот"}, {"zh": "文旅融合", "pinyin": "wénlǚ rónghé", "mn": "соёл ба аялал жуулчлалын нэгдэл"}, {"zh": "交通中心", "pinyin": "jiāotōng zhōngxīn", "mn": "тээврийн төв"}, {"zh": "潜力", "pinyin": "qiánlì", "mn": "нөөц бололцоо"}], "transcript": [{"zh": "武汉作为中国历史文化名城，拥有丰富的文化遗产。", "mn": "Ухань бол Хятадын түүх соёлын алдартай хот бөгөөд баялаг соёлын өвтэй."}, {"zh": "如今，这座历史悠久的商业中心已发展成为充满活力的现代都市。", "mn": "Өнөөдөр энэ эртний наймааны төв эрч хүчтэй орчин үеийн хот болон өсчээ."}, {"zh": "通过科技创新与文旅融合，古老的历史街区获得了新的生命力。", "mn": "Шинжлэх ухаан технологийн шинэчлэл, соёл аялал жуулчлалын нэгдлээр эртний түүхэт гудамжууд шинэ амьдрал олжээ."}, {"zh": "作为连接各地的交通中心，武汉在经济发展中展现出巨大的潜力，吸引着世界各地的游客。", "mn": "Орон бүрийг холбосон тээврийн төв болохынхоо хувьд Ухань эдийн засгийн хөгжилд асар их нөөц бололцоо харуулж, дэлхийн өнцөг булан бүрээс жуулчдыг татаж байна."}]}'::jsonb),
('M62601','listening',2,9,'choice','','[{"key": "A", "text": "工作地点受到限制"}, {"key": "B", "text": "主要从事体力劳动"}, {"key": "C", "text": "依赖数字技术办公"}, {"key": "D", "text": "已经取代传统行业"}]'::jsonb,'C','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эхэнд «数字游民，是指利用数字技术办公……的人» гэж тодорхойлсон. Тиймээс дижитал технологид тулгуурласан ажил гэсэн C зөв.',392.15,560.48,'随着互联网技术的飞速发展，一种名为“数字游民”的就业形式正悄然兴起。“数字游民”，是指利用数字技术办公，彻底摆脱了固定办公地点的限制，能够在全球范围内自由选择居住地的人。出现“数字游民”这一现象在当代职场中引发了广泛的关注与讨论。对许多年轻人来说，成为“数字游民”不仅能够避开上下班高峰期的拥堵，更是一种对生活质量的重新定义。他们可以坐在海边的咖啡馆处理软件开发任务，也可以在安宁的乡村小镇拟订策划方案。这种模式不仅提高了工作的灵活性，也在很大程度上缓解了竞争压力带来的焦虑。然而，这种看似自由的职业状态也面临着现实的挑战。由于缺乏稳定的社交圈和固定的生活节奏，一些“数字游民”会感到孤独，甚至难以分清工作与生活的界限，导致身心疲惫。专家指出，这种趋势反映了人们对传统劳动模式的反思。未来，随着相关社会保障制度的日益完善，这种灵活的就业形式或许会成为更多人的选择。
问：关于“数字游民”，可以知道什么？','{"why": "Эхэнд «数字游民，是指利用数字技术办公……的人» гэж тодорхойлсон. Тиймээс дижитал технологид тулгуурласан ажил гэсэн C зөв.", "key": "是指利用数字技术办公……的人", "keyMn": "Дижитал технологиор ажилладаг хүн", "wrong": {"A": "Тэд «摆脱了固定办公地点的限制» тул байршил хязгаарлагдахгүй.", "B": "Жишээ нь програм хөгжүүлэх, төлөвлөгөө боловсруулах: оюун ухааны ажил.", "D": "Зөвхөн «兴起» гэсэн, уламжлалт салбарыг орлосон гэсэн зүйл алга."}, "words": [{"zh": "数字游民", "pinyin": "shùzì yóumín", "mn": "дижитал нүүдэлчин"}, {"zh": "摆脱", "pinyin": "bǎituō", "mn": "салах, ангижрах"}, {"zh": "办公", "pinyin": "bàngōng", "mn": "албан ажил хийх"}, {"zh": "兴起", "pinyin": "xīngqǐ", "mn": "шинээр өрнөх"}], "transcript": [{"zh": "随着互联网技术的飞速发展，一种名为“数字游民”的就业形式正悄然兴起。", "mn": "Интернет технологи огцом хөгжихийн хэрээр «дижитал нүүдэлчин» хэмээх хөдөлмөр эрхлэлтийн хэлбэр чимээгүйхэн өрнөж байна."}, {"zh": "“数字游民”，是指利用数字技术办公，彻底摆脱了固定办公地点的限制，能够在全球范围内自由选择居住地的人。", "mn": "«Дижитал нүүдэлчин» гэдэг нь дижитал технологиор ажиллаж, тогтсон ажлын байрны хязгаарлалтаас бүрэн салж, дэлхийн хаана ч дуртай газраа амьдрахаар сонгож чадах хүн юм."}, {"zh": "出现“数字游民”这一现象在当代职场中引发了广泛的关注与讨论。", "mn": "Энэ үзэгдэл орчин үеийн ажил мэргэжлийн ертөнцөд өргөн анхаарал, хэлэлцүүлэг татсан."}, {"zh": "对许多年轻人来说，成为“数字游民”不仅能够避开上下班高峰期的拥堵，更是一种对生活质量的重新定义。", "mn": "Олон залуугийн хувьд «дижитал нүүдэлчин» болох нь ажилд ирэх, буцах ачааллын түгжрэлээс зайлсхийхээс гадна амьдралын чанарыг шинээр тодорхойлох явдал юм."}, {"zh": "他们可以坐在海边的咖啡馆处理软件开发任务，也可以在安宁的乡村小镇拟订策划方案。", "mn": "Тэд далайн эргийн кафед суугаад програм хангамж хөгжүүлэх ажлаа хийж, эсвэл нам гүм хөдөөгийн жижиг хотод төлөвлөгөө боловсруулж болно."}, {"zh": "这种模式不仅提高了工作的灵活性，也在很大程度上缓解了竞争压力带来的焦虑。", "mn": "Энэ хэлбэр ажлын уян хатан байдлыг нэмэгдүүлээд зогсохгүй өрсөлдөөний дарамтаас үүдэх түгшүүрийг ихээхэн багасгасан."}, {"zh": "然而，这种看似自由的职业状态也面临着现实的挑战。", "mn": "Гэвч эрх чөлөөтэй мэт энэ ажлын байдал бодит сорилттой тулгарч байна."}, {"zh": "由于缺乏稳定的社交圈和固定的生活节奏，一些“数字游民”会感到孤独，甚至难以分清工作与生活的界限，导致身心疲惫。", "mn": "Тогтвортой нийгмийн орчин, тогтсон амьдралын хэмнэл дутагдсанаас зарим «дижитал нүүдэлчин» ганцаардаж, ажил амьдралынхаа зааг ялгахад хүртэл хэцүү болж, бие сэтгэл нь ядардаг."}, {"zh": "专家指出，这种趋势反映了人们对传统劳动模式的反思。", "mn": "Мэргэжилтнүүд энэ чиг хандлага нь хүмүүс уламжлалт хөдөлмөрийн хэлбэрийг эргэн бодож байгааг илтгэнэ гэж онцолжээ."}, {"zh": "未来，随着相关社会保障制度的日益完善，这种灵活的就业形式或许会成为更多人的选择。", "mn": "Ирээдүйд нийгмийн хамгааллын холбогдох тогтолцоо улам төгөлдөржихийн хэрээр ийм уян хатан хөдөлмөр эрхлэлт илүү олон хүний сонголт болж магадгүй."}, {"zh": "问：关于“数字游民”，可以知道什么？", "mn": "Асуулт: «Дижитал нүүдэлчин»-ийн талаар юу мэдэж болох вэ?"}]}'::jsonb),
('M62601','listening',2,10,'choice','','[{"key": "A", "text": "收入比以前大幅增加了"}, {"key": "B", "text": "不需要处理复杂的任务"}, {"key": "C", "text": "能够获得政府的补贴款"}, {"key": "D", "text": "工作时间和地点更灵活"}]'::jsonb,'D','auto',1,'/mock-tests/m62601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «这种模式不仅提高了工作的灵活性» гэж хэлээд цаг, газраа сонгох боломжийг дурдсан. Тиймээс D зөв.',392.15,560.48,'随着互联网技术的飞速发展，一种名为“数字游民”的就业形式正悄然兴起。“数字游民”，是指利用数字技术办公，彻底摆脱了固定办公地点的限制，能够在全球范围内自由选择居住地的人。出现“数字游民”这一现象在当代职场中引发了广泛的关注与讨论。对许多年轻人来说，成为“数字游民”不仅能够避开上下班高峰期的拥堵，更是一种对生活质量的重新定义。他们可以坐在海边的咖啡馆处理软件开发任务，也可以在安宁的乡村小镇拟订策划方案。这种模式不仅提高了工作的灵活性，也在很大程度上缓解了竞争压力带来的焦虑。然而，这种看似自由的职业状态也面临着现实的挑战。由于缺乏稳定的社交圈和固定的生活节奏，一些“数字游民”会感到孤独，甚至难以分清工作与生活的界限，导致身心疲惫。专家指出，这种趋势反映了人们对传统劳动模式的反思。未来，随着相关社会保障制度的日益完善，这种灵活的就业形式或许会成为更多人的选择。
问：“数字游民”受到年轻人欢迎的主要原因是什么？','{"why": "Эх «这种模式不仅提高了工作的灵活性» гэж хэлээд цаг, газраа сонгох боломжийг дурдсан. Тиймээс D зөв.", "key": "提高了工作的灵活性", "keyMn": "Ажлын уян хатан байдлыг нэмсэн", "wrong": {"A": "Орлогын талаар огт ярьсангүй.", "B": "Программ хөгжүүлэх зэрэг ажил нь нарийн төвөгтэй.", "C": "Нийгмийн хамгаалал «日益完善» болох цаг ирээдүйд гэсэн, одоо татаас авдаг гэсэн зүйл алга."}, "words": [{"zh": "灵活性", "pinyin": "línghuóxìng", "mn": "уян хатан байдал"}, {"zh": "高峰期", "pinyin": "gāofēngqī", "mn": "ачааллын оргил цаг"}, {"zh": "拥堵", "pinyin": "yōngdǔ", "mn": "түгжрэл"}, {"zh": "重新定义", "pinyin": "chóngxīn dìngyì", "mn": "шинээр тодорхойлох"}], "transcript": [{"zh": "随着互联网技术的飞速发展，一种名为“数字游民”的就业形式正悄然兴起。", "mn": "Интернет технологи огцом хөгжихийн хэрээр «дижитал нүүдэлчин» хэмээх хөдөлмөр эрхлэлтийн хэлбэр чимээгүйхэн өрнөж байна."}, {"zh": "“数字游民”，是指利用数字技术办公，彻底摆脱了固定办公地点的限制，能够在全球范围内自由选择居住地的人。", "mn": "«Дижитал нүүдэлчин» гэдэг нь дижитал технологиор ажиллаж, тогтсон ажлын байрны хязгаарлалтаас бүрэн салж, дэлхийн хаана ч дуртай газраа амьдрахаар сонгож чадах хүн юм."}, {"zh": "出现“数字游民”这一现象在当代职场中引发了广泛的关注与讨论。", "mn": "Энэ үзэгдэл орчин үеийн ажил мэргэжлийн ертөнцөд өргөн анхаарал, хэлэлцүүлэг татсан."}, {"zh": "对许多年轻人来说，成为“数字游民”不仅能够避开上下班高峰期的拥堵，更是一种对生活质量的重新定义。", "mn": "Олон залуугийн хувьд «дижитал нүүдэлчин» болох нь ажилд ирэх, буцах ачааллын түгжрэлээс зайлсхийхээс гадна амьдралын чанарыг шинээр тодорхойлох явдал юм."}, {"zh": "他们可以坐在海边的咖啡馆处理软件开发任务，也可以在安宁的乡村小镇拟订策划方案。", "mn": "Тэд далайн эргийн кафед суугаад програм хангамж хөгжүүлэх ажлаа хийж, эсвэл нам гүм хөдөөгийн жижиг хотод төлөвлөгөө боловсруулж болно."}, {"zh": "这种模式不仅提高了工作的灵活性，也在很大程度上缓解了竞争压力带来的焦虑。", "mn": "Энэ хэлбэр ажлын уян хатан байдлыг нэмэгдүүлээд зогсохгүй өрсөлдөөний дарамтаас үүдэх түгшүүрийг ихээхэн багасгасан."}, {"zh": "然而，这种看似自由的职业状态也面临着现实的挑战。", "mn": "Гэвч эрх чөлөөтэй мэт энэ ажлын байдал бодит сорилттой тулгарч байна."}, {"zh": "由于缺乏稳定的社交圈和固定的生活节奏，一些“数字游民”会感到孤独，甚至难以分清工作与生活的界限，导致身心疲惫。", "mn": "Тогтвортой нийгмийн орчин, тогтсон амьдралын хэмнэл дутагдсанаас зарим «дижитал нүүдэлчин» ганцаардаж, ажил амьдралынхаа зааг ялгахад хүртэл хэцүү болж, бие сэтгэл нь ядардаг."}, {"zh": "专家指出，这种趋势反映了人们对传统劳动模式的反思。", "mn": "Мэргэжилтнүүд энэ чиг хандлага нь хүмүүс уламжлалт хөдөлмөрийн хэлбэрийг эргэн бодож байгааг илтгэнэ гэж онцолжээ."}, {"zh": "未来，随着相关社会保障制度的日益完善，这种灵活的就业形式或许会成为更多人的选择。", "mn": "Ирээдүйд нийгмийн хамгааллын холбогдох тогтолцоо улам төгөлдөржихийн хэрээр ийм уян хатан хөдөлмөр эрхлэлт илүү олон хүний сонголт болж магадгүй."}, {"zh": "问：“数字游民”受到年轻人欢迎的主要原因是什么？", "mn": "Асуулт: «Дижитал нүүдэлчин» залуусад таалагдах гол шалтгаан юу вэ?"}]}'::jsonb),
